import React from "react";
import { Button, Container, Row, Col, Card } from "react-bootstrap";
import { useHistory } from "react-router-dom";
import { SHOP_ROUTE } from "../utils/const";

const Admin = () => {
    const history = useHistory();

    return (
        <Container className="mt-4">
            <h2 className="text-center mb-4">Панель администратора</h2>
            
            <Row className="justify-content-center">
                <Col md={8} lg={6}>
                    <Card className="p-4">
                        <div className="d-flex flex-column gap-3">
                            {/* Кнопка для перехода в каталог товаров */}
                            <Button
                                variant="outline-primary"
                                size="lg"
                                onClick={() => history.push(SHOP_ROUTE)}
                                className="py-3"
                            >
                                📦 Каталог товаров
                            </Button>
                            
                            {/* Кнопка добавления типа */}
                            <Button
                                variant="outline-success"
                                size="lg"
                                onClick={() => history.push('/admin/add-type')}
                                className="py-3"
                            >
                                ➕ Добавить тип товара
                            </Button>
                            
                            {/* Кнопка просмотра пользователей */}
                            <Button
                                variant="outline-info"
                                size="lg"
                                onClick={() => history.push('/admin/users')}
                                className="py-3"
                            >
                                👥 Просмотр пользователей
                            </Button>
                        </div>
                    </Card>
                </Col>
            </Row>
        </Container>
    );
}

export default Admin;
